export type SettingsCopyKey = keyof typeof COPY;
export const SETTINGS_COPY_ENGLISH: Readonly<Record<SettingsCopyKey, string>> = Object.fromEntries(
  Object.keys(COPY).map((key) => [key, key]),
) as Record<SettingsCopyKey, string>;

const SOURCE_TO_KEY = new Map<string, SettingsCopyKey>();
for (const key of Object.keys(COPY) as SettingsCopyKey[]) SOURCE_TO_KEY.set(key, key);

const LANG_INDEX: Record<Exclude<Language, "en">, 0 | 1 | 2> = { uk: 0, pl: 1, ru: 2 };
export function tSettings(key: SettingsCopyKey, language: Language = "en", params: Record<string, string | number> = {}): string {
  const raw = language === "en" ? key : COPY[key][LANG_INDEX[language]];
  return raw.replace(/\{([a-zA-Z][\w]*)\}/g, (match, name: string) => name in params ? String(params[name]) : match);
}

/** Exact UI strings and simple parameterized templates; unknown/user-provided text remains untouched. */
export function translateSettingsSource(source: string, language: Language): string {
  const exact = SOURCE_TO_KEY.get(source);
  if (exact) return tSettings(exact, language);
  const templates: SettingsCopyKey[] = [
    "Changes to {file}", "Lines found in {file}", "Nothing would change: {file} already says this.",
    "Could not write: {reason}", "Not receiving Claude Code events: {reason}",
    "Click again to reset {section}.", "{section} is reset.",
    "Open {section}", "In {section}. Open it.", "Three at most. Untick one to show {name}.",
    "{count} of {total} chosen", "{count} of {total} on",
    "{name}: {where}. Opens in your browser.",
    "Nook {version} is out. Get it opens its download page in your browser.", "Checked {date}.", "Version {version}",
    "Nothing matches “{query}”. Try a simpler word.", "You have version {version}",
    "Follows your computer, which is set to {theme} right now. The island itself is always dark.",
    "Missing events: {events}. Repair adds Nook's missing entries and keeps your other hooks.",
    "Nook prints no status line of its own. {hints}", "You have no status line: Nook prints none. {hints}",
  ];
  for (const key of templates) {
    if (key === "Not receiving Claude Code events: {reason}" && !source.startsWith("Not receiving Claude Code events: ")) continue;
    if (key === "Could not write: {reason}" && !source.startsWith("Could not write: ")) continue;
    if (key === "Click again to reset {section}." && !source.startsWith("Click again to reset ")) continue;
    if (key === "{section} is reset." && !source.endsWith(" is reset.")) continue;
    const names: string[] = [];
    for (const candidate of [key]) {
      names.length = 0;
      const template = candidate.replace(/\{([a-zA-Z][\w]*)\}/g, (_m, name: string) => {
        names.push(name);
        return "\u0000";
      });
      const escaped = template.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\u0000/g, "([\\s\\S]*?)");
      const pattern = new RegExp(`^${escaped}$`);
      const match = source.match(pattern);
      if (match && names.length && !source.startsWith(key.slice(0, key.indexOf("{")))) continue;
      if (match) {
        const localizable = new Set(["section", "label", "name", "theme"]);
        const params = Object.fromEntries(names.map((name, i) => {
          const value = match[i + 1];
          const parameterKey = SOURCE_TO_KEY.get(value);
          return [name, localizable.has(name) && parameterKey ? tSettings(parameterKey, language) : value];
        }));
        return tSettings(key, language, params);
      }
    }
  }
  return source;
}

export function settingsCopyKeys(): readonly SettingsCopyKey[] {
  return Object.keys(COPY) as SettingsCopyKey[];
}

/** Builds the same translated plus source-language search metadata used by Settings. */
export function settingsSearchWords(label: string, help: string | null, sectionName: string, keys: string, language: Language, extra = ""): string {
  const localized = [translateSettingsSource(label, language), help ? translateSettingsSource(help, language) : "", translateSettingsSource(sectionName, language), label, help ?? "", sectionName, keys, extra];
  return localized.join(" ").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[“”\"'‘’]/g, "");
}

/** Every query word must occur somewhere in the indexed metadata. */
export function settingsSearchMatches(indexWords: string, query: string): boolean {
  const normalized = query.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[“”\"'‘’]/g, "");
  return normalized.trim().split(/\s+/).filter(Boolean).every((word) => indexWords.includes(word));
}

export function searchResultCount(count: number, language: Language): string {
  const n = formatNumber(count, language);
  const category = pluralCategory(count, language);
  if (language === "en") return `${n} ${count === 1 ? "setting" : "settings"} found.`;
  const forms: Record<Exclude<Language, "en">, Record<string, string>> = {
    uk: { one: `Знайдено ${n} налаштування.`, few: `Знайдено ${n} налаштування.`, many: `Знайдено ${n} налаштувань.`, other: `Знайдено ${n} налаштування.` },
    pl: { one: `Znaleziono ${n} ustawienie.`, few: `Znaleziono ${n} ustawienia.`, many: `Znaleziono ${n} ustawień.`, other: `Znaleziono ${n} ustawienia.` },
    ru: { one: `Найдена ${n} настройка.`, few: `Найдено ${n} настройки.`, many: `Найдено ${n} настроек.`, other: `Найдено ${n} настройки.` },
  };
  return forms[language][category] ?? forms[language].other;
}
